import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { startLiveBot } from "../services/api";

const LiveMeetingBot = () => {
  const [link, setLink] = useState("");
  const [loading, setLoading] = useState(false);
  const [botJoined, setBotJoined] = useState(false);
  const [error, setError] = useState("");

  const navigate = useNavigate();

  // 🔹 Listen when extension finishes recording
  useEffect(() => {
    const handleMeetingEnd = async (event) => {
      try {
        const audioBlob = event.detail.audio;

        if (!audioBlob) {
          throw new Error("No audio received");
        }

        const formData = new FormData();
        formData.append("audio", audioBlob, "meeting.webm");

        const res = await axios.post(
          "http://localhost:5000/api/livebot/end",
          formData
        );

        navigate("/result", { state: res.data });

      } catch (err) {
        console.error(err);
        setError("Meeting analysis failed");
      }
    };

    window.addEventListener("meeting-ended", handleMeetingEnd);
    return () => window.removeEventListener("meeting-ended", handleMeetingEnd);
  }, [navigate]);

  // 🔹 Start bot + recording
  const handleStartBot = async () => {
    if (!link.trim()) {
      setError("Please enter a valid meeting link");
      return;
    }

    try {
      setLoading(true);
      setError("");

      await startLiveBot({ meetingLink: link });

      setBotJoined(true);

      // 🔹 Tell extension to start recording
      window.postMessage({ type: "START_RECORDING" }, "*");

    } catch (err) {
      console.error(err);
      setError("Failed to start meeting bot");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="card">
      <h2>Live Meeting Assistant</h2>

      <input
        type="text"
        placeholder="Paste Google Meet / Zoom link"
        value={link}
        disabled={botJoined}
        onChange={(e) => setLink(e.target.value)}
      />

      {error && <p style={{ color: "red" }}>{error}</p>}

      {botJoined ? (
        <p style={{ color: "green", fontWeight: "bold" }}>
          🤖 Bot joined. Recording in progress…
        </p>
      ) : (
        <button onClick={handleStartBot} disabled={loading}>
          {loading ? "Joining…" : "Start Meeting Bot"}
        </button>
      )}
    </div>
  );
};

export default LiveMeetingBot;
